import React from 'react';

import { mapValueToDomain } from './functions/map-value-to-domain.js';
import { useThresholdBarTooltip } from './hooks/useThresholdBarTooltip.js';
import { CircleMarker } from './markers/CircleMarker.js';
import { PillMarker } from './markers/PillMarker.js';
import { wrapper } from './styles.sty.js';
import { ThresholdBarProps } from './ThresholdBar.js';
import { THRESHOLD_BAR_THICKNESS } from './types/constants.js';
import { InteractiveChartTooltip } from '../tooltip/InteractiveChartTooltip/components/InteractiveChartTooltip.js';
import { SeriesBasedContent } from '../tooltip/InteractiveChartTooltip/contents/SeriesBasedContent.js';

type LayoutType =
  | 'vertical-flip'
  | 'vertical-no-flip'
  | 'horizontal-flip'
  | 'horizontal-no-flip';

export const ThresholdBarTemplate = (props: ThresholdBarProps) => {
  const {
    scale,
    length,
    markers,
    layout = 'vertical',
    isFlipped = false,
    formatter = (value) => `${value}`,
    onHover,
  } = props;

  const {
    showTooltip,
    tooltipPosition,
    tooltipItems,
    handleMouseMove,
    handleMouseLeave,
  } = useThresholdBarTooltip(markers, formatter, onHover);

  const flipType = isFlipped ? 'flip' : 'no-flip';
  const layoutType: LayoutType = `${layout}-${flipType}`;

  return (
    <div className={wrapper({ layoutType })} style={{ height: length }}>
      <svg width={THRESHOLD_BAR_THICKNESS} height={length}>
        {markers.map((marker, index) => {
          const { y0, y1, color } = marker;

          if (y0 === y1) {
            return (
              <CircleMarker
                x={8}
                y={scale(y0) ?? 0}
                color={color}
                key={`threshold-bar-circle-marker-${marker.id}`}
                onMouseMove={(event) => handleMouseMove(event, index)}
                onMouseLeave={handleMouseLeave}
              />
            );
          }

          return (
            <PillMarker
              x={4}
              y0={mapValueToDomain(y0, scale)}
              y1={mapValueToDomain(y1, scale)}
              color={color}
              key={`threshold-bar-pill-marker-${marker.id}`}
              onMouseMove={(event) => handleMouseMove(event, index)}
              onMouseLeave={handleMouseLeave}
            />
          );
        })}
      </svg>
      {showTooltip && (
        <InteractiveChartTooltip position={tooltipPosition!}>
          <InteractiveChartTooltip.Body>
            {tooltipItems.map((tooltipItem, index) => (
              <SeriesBasedContent
                key={`threshold-bar-tooltip-item-${tooltipItem.id}`}
                item={tooltipItem}
                showDivider={index !== tooltipItems.length - 1}
              />
            ))}
          </InteractiveChartTooltip.Body>
        </InteractiveChartTooltip>
      )}
    </div>
  );
};

ThresholdBarTemplate['displayName'] = 'ThresholdBarTemplate';
